#!/usr/bin/env node
// S.T.A.N.D.A.R.D.S. command-line installer.
import { cpSync, existsSync, lstatSync, mkdirSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

const VERSION = '0.6.0';
const MARKER = '<!-- standards:framework-owned -->';
const USAGE = [
  'Usage: standards <command> [options]',
  '',
  'Commands:',
  '  install     Install STANDARDS into a project',
  '  upgrade     Upgrade an installed project to this version',
  '  reset       Return the workflow to the state of a fresh installation',
  '  uninstall   Remove STANDARDS from a project',
  '',
  'Options:',
  '  --project <path>   Project folder (default: current folder)',
  '  --mode <mode>      greenfield or brownfield',
  '  --dry-run          Report every planned change without writing files',
  '  --yes              Apply without asking for confirmation',
  '  --version          Print the CLI version',
].join('\n');
const KEPT = '.standards/PROTOCOL.md, .standards/protocol/, .standards/bin/, .standards/VERSION.json, '
  + '.standards/INSTALLATION.json, .standards/user-styles/, skills, hooks, client settings, managed blocks';
// Top-level entries that do not by themselves make a project brownfield.
const SETUP_ENTRIES = new Set(['.git', '.gitignore', '.npmrc', '.standards', '.claude', '.codex', '.agents',
  'node_modules', 'AGENTS.md', 'CLAUDE.md', 'README.md', 'LICENSE', 'package.json', 'package-lock.json']);

class CliError extends Error {}

const plural = (count, word) => count + ' ' + word + (count === 1 ? '' : 's');

function parseArgs(argv) {
  const options = { command: null, project: null, mode: null, dryRun: false, yes: false, version: false, help: false };
  for (let index = 0; index < argv.length; index += 1) {
    const [name, inline] = argv[index].split(/=(.*)/s, 2);
    const value = () => {
      const next = inline ?? argv[(index += 1)];
      if (!next) throw new CliError(name + ' needs a value.');
      return next;
    };
    if (name === '--project') options.project = value();
    else if (name === '--mode') options.mode = value();
    else if (name === '--dry-run') options.dryRun = true;
    else if (name === '--yes' || name === '-y') options.yes = true;
    else if (name === '--version' || name === '-v') options.version = true;
    else if (name === '--help' || name === '-h') options.help = true;
    else if (!name.startsWith('-') && options.command === null) options.command = name;
    else throw new CliError('Unknown argument ' + argv[index] + '.\n\n' + USAGE);
  }
  return options;
}

function readText(file) {
  try {
    return readFileSync(file, 'utf8');
  } catch {
    return null;
  }
}

function countRecords(dir) {
  let count = 0;
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    const child = path.join(dir, entry.name);
    if (entry.isDirectory()) count += countRecords(child);
    else if (entry.isFile() && entry.name.endsWith('.md')) count += 1;
  }
  return count;
}

function stateTemplate(mode) {
  const start = mode === 'GREENFIELD' ? 'SCOPING' : 'AUDITING';
  return [
    '# S.T.A.N.D.A.R.D.S. Workflow State',
    '',
    '`WorkflowState`: `' + start + '` `CycleMode`: `UNSET` `PendingCycleMode`: `UNSET`',
    '`PendingCycleRequest`: `UNSET` `PendingCycleBlockedOn`: `NONE`',
    '',
    '## Active Work',
    '',
    '`CompletionPolicy`: `NONE`',
    '`Id`: `UNSET` `Request`: `UNSET` `Scope`: `NONE` `Architecture`: `NONE`',
    '`Development`: `NONE` `PromotionReason`: `NONE` `AuditTarget`: `NONE`',
    '`BlockedOn`: `NONE` `PendingVerificationCadence`: `NONE`',
    '',
    '`BaselineReconciliation`: `NONE`',
    '',
    '<!-- When non-NONE, use one Markdown list entry per source cycle:',
    '- `SourceCycle`: `<cancelled-cycle-id>`',
    '  `Request`: `<source-cycle request summary>`',
    'Preserve existing entries; see PROTOCOL.md, Baseline Reconciliation Format.',
    '-->',
    '',
    '## Handoff',
    '',
    '`Kind`: `INITIAL` `From`: `NONE` `FailureType`: `NONE` `Reason`:',
    '`Initial ' + mode.toLowerCase() + ' workflow state; cycle mode not yet selected.`',
    '',
    '## Recovery',
    '',
    '`Active`: `false`',
    '',
    '## Outstanding Obligations',
    '',
    '`Active`: `false`',
    '',
  ].join('\n');
}

function modeTemplate(mode) {
  return ['# S.T.A.N.D.A.R.D.S. Project Mode', '', '`ProjectMode`: `' + mode + '`', ''].join('\n');
}

function reset(options) {
  const root = path.resolve(options.project ?? process.cwd());
  const standards = path.join(root, '.standards');
  if (!readText(path.join(standards, 'PROTOCOL.md'))?.includes(MARKER)) {
    throw new CliError('No STANDARDS installation found at ' + root + '.');
  }
  let installed;
  try {
    installed = JSON.parse(readFileSync(path.join(standards, 'VERSION.json'), 'utf8')).version;
  } catch {
    throw new CliError(path.join(standards, 'VERSION.json') + ' is missing or invalid.');
  }
  if (installed !== VERSION) {
    throw new CliError('This project has STANDARDS ' + installed + ' installed, but this CLI is ' + VERSION
      + '. Reset writes fresh files from the CLI templates, so the versions must match. No files were changed.');
  }
  let mode;
  let source;
  if (options.mode) {
    mode = options.mode.toUpperCase();
    if (!['GREENFIELD', 'BROWNFIELD'].includes(mode)) throw new CliError('--mode must be greenfield or brownfield.');
    source = 'from --mode';
  } else {
    mode = readdirSync(root).some((name) => !SETUP_ENTRIES.has(name)) ? 'BROWNFIELD' : 'GREENFIELD';
    source = 'chosen from project contents';
  }
  const deletions = [];
  for (const relative of ['.standards/CONTEXT.md', '.standards/docs']) {
    const full = path.join(root, relative);
    let entry;
    try {
      entry = lstatSync(full);
    } catch {
      continue;
    }
    if (entry.isSymbolicLink()) {
      throw new CliError('Refusing to reset: ' + relative + ' is a symbolic link. No files were changed.');
    }
    deletions.push({ relative, full, folder: entry.isDirectory(), records: entry.isDirectory() ? countRecords(full) : 0 });
  }
  const records = deletions.reduce((sum, item) => sum + item.records, 0);
  const describe = (item) => (item.folder
    ? item.relative + '/ (' + plural(item.records, 'cycle record') + ')'
    : item.relative + ' (project context)');
  const warnings = [];
  if (deletions.some((item) => !item.folder)) warnings.push('Warning: the project context in .standards/CONTEXT.md will be deleted.');
  if (records) warnings.push('Warning: ' + plural(records, 'cycle record') + ' under .standards/docs/ will be deleted.');
  const lines = ['STANDARDS ' + VERSION + ' reset' + (options.dryRun ? ' (dry run)' : ''), 'Project: ' + root,
    'Mode: ' + mode + ' (' + source + ')', ''];
  if (options.dryRun) {
    lines.push('Planned changes:', ...deletions.map((item) => '  delete  ' + describe(item)),
      '  write   .standards/STATE.md (fresh workflow state)', '  write   .standards/MODE.md (' + mode + ')',
      '', 'Kept: ' + KEPT, '');
    if (warnings.length) lines.push(...warnings, '');
    lines.push('Dry run: no files were changed.');
    process.stdout.write(lines.join('\n') + '\n');
    return;
  }
  if (!options.yes) {
    throw new CliError('reset deletes workflow data. Preview it with --dry-run, then run it again with --yes to apply. No files were changed.');
  }
  const backup = mkdtempSync(path.join(os.tmpdir(), 'standards-reset-'));
  const saved = [...deletions.map((item) => item.relative), '.standards/STATE.md', '.standards/MODE.md']
    .filter((relative) => existsSync(path.join(root, relative)));
  for (const relative of saved) {
    mkdirSync(path.dirname(path.join(backup, relative)), { recursive: true });
    cpSync(path.join(root, relative), path.join(backup, relative), { recursive: true });
  }
  try {
    for (const item of deletions) rmSync(item.full, { recursive: true, force: true });
    writeFileSync(path.join(standards, 'STATE.md'), stateTemplate(mode));
    writeFileSync(path.join(standards, 'MODE.md'), modeTemplate(mode));
  } catch (error) {
    try {
      for (const relative of saved) {
        rmSync(path.join(root, relative), { recursive: true, force: true });
        cpSync(path.join(backup, relative), path.join(root, relative), { recursive: true });
      }
    } catch {
      throw new CliError('Reset failed (' + error.message + ') and could not be rolled back. Backups are in ' + backup + '.');
    }
    rmSync(backup, { recursive: true, force: true });
    throw new CliError('Reset failed and was rolled back: ' + error.message);
  }
  rmSync(backup, { recursive: true, force: true });
  if (warnings.length) lines.push(...warnings, '');
  lines.push(...deletions.map((item) => 'deleted ' + describe(item)),
    'wrote   .standards/STATE.md', 'wrote   .standards/MODE.md', '', 'Reset complete.');
  process.stdout.write(lines.join('\n') + '\n');
}

try {
  const options = parseArgs(process.argv.slice(2));
  if (options.version) process.stdout.write(VERSION + '\n');
  else if (options.help || options.command === null) process.stdout.write(USAGE + '\n');
  else if (options.command === 'reset') reset(options);
  else if (['install', 'upgrade', 'uninstall'].includes(options.command)) {
    throw new CliError(options.command + ' must be run from an interactive terminal.');
  } else {
    throw new CliError('Unknown command ' + options.command + '.\n\n' + USAGE);
  }
} catch (error) {
  process.stderr.write('standards: ' + (error instanceof CliError ? error.message : 'unexpected error: ' + error.message) + '\n');
  process.exitCode = 1;
}
